from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/"questions/social";LESSON="lesson-social-content-hist-j-iv-1";KG="kg-social-content-hist-j-iv-1";TARGETS=["A","B","C","D","A","B","C","D","B","C"]
FOCI=[("問題聚焦與可查證性","問題要有時間、地點、對象和可取得證據，不能用『一直』或『大家』把範圍無限放大。"),("照片來源與定位","日期、拍攝者、地點和版本是照片的來源條件，招牌辨識不能取代完整定位。"),("口述記憶的差異","不同回憶可能反映位置、經驗和選擇性記憶，應與照片、帳冊或報紙互證。"),("田野倫理與同意","拍攝住家和訪談未成年人涉及隱私、監護同意、匿名與可撤回的倫理要求。"),("觀察與結論界線","一個入口招牌只能支持局部觀察，不能直接推論整個市場或所有居民已現代化。"),("地方事件時間線","建站、改線、商店與拆遷要先核對年代和因果證據，不把排列順序當成自動因果。"),("展演中的多方證據","有限展板應並置官方成果和居民經驗，標明資料來源與仍未解答的部分。"),("歷史地圖與現地變化","舊地圖和現地排水溝需查比例、改道、填築與地名，提出可檢驗而非唯一的解釋。"),("樣本偏差與訪談範圍","白天店家不能代表夜間攤販與居民，報告需說明樣本限制並補訪不同時段。"),("變遷結論與不確定性","繁榮、衰退和復甦可能同時存在於不同時段或群體，結論要限定證據範圍。")]
SOURCES=[{"url":"https://www.yacjh.kh.edu.tw/upload/221/101_30637/114%E4%B8%8B%E5%AD%B8%E6%9C%9F%E7%AC%AC%E4%B8%80%E6%AC%A1%E6%AE%B5%E8%80%83%E4%B8%89%E5%B9%B4%E7%B4%9A%E7%9A%84%E7%A4%BE%E6%9C%83.pdf","title":"高雄市立鹽埕國民中學公開段考社會科；僅研究地方資料、探究與證據判讀題型，未複製原題。","year":"114","locator":"公開段考社會科 PDF；第 1 題至第 10 題型範圍：資料判讀、時序與因果界線","observedPattern":"由地圖、文字與生活材料要求學生界定證據、樣本與歷史結論範圍。"},{"url":"https://affairs.kh.edu.tw/1126/upload/file_list/149","title":"高雄市立文府國民中學公開社會科試題入口；僅研究多資料互證題型，未複製原題。","year":"113-114","locator":"公開試題與解答入口；第 1 題至第 10 題型範圍：地方資料、時序與多重證據","observedPattern":"比較地圖、記錄與角色經驗，區分直接觀察、推論與待補證主張。"},{"url":"https://www.dwm.kh.edu.tw/view/index.php?MainMenuId=64182&MainType=0&SubMenuId=64184&SubType=104&WebID=344","title":"高雄市立大灣國民中學公開段考試題入口；僅研究地方探究與多方觀點題型，未複製原題。","year":"113-114","locator":"公開段考試題入口；第 1 題至第 10 題型範圍：地方史、社會變遷與多方角色","observedPattern":"從地方材料分析樣本、證據與群體差異，不以單一來源包辦結論。"}]
def refs():return[{**x,"subject":"social","reuseDecision":"pattern-only","status":"recorded","locatorLevel":"paper"}for x in SOURCES]
for i,target in enumerate(TARGETS,1):
 p=OUT/f"question-social-content-hist-j-iv-1-{i}.json";d=json.loads(p.read_text(encoding="utf-8"));assert d["lessonId"]==LESSON and d["knowledgeIds"]==[KG];old=d["answer"]["value"];oi=ord(old)-65;correct=d["options"][oi]["text"];rest=[x["text"]for j,x in enumerate(d["options"])if j!=oi];ti=ord(target)-65;ordered=rest[:ti]+[correct]+rest[ti:];d["options"]=[{"id":chr(65+j),"text":x}for j,x in enumerate(ordered)];focus,reason=FOCI[i-1]
 d["answer"]={"value":target,"explanation":f"本題聚焦「{focus}」。{reason} 正確答案為選項 {target}：「{correct}」。"};d["solutionStrategy"]=f"先定位{focus}的問題範圍、資料來源、樣本與倫理，再區分觀察、推論和仍待查證的主張；{reason}"
 d["solutionSteps"]=[f"讀題定位：圈出研究問題、地點、資料和參與者，確認本題正在檢核「{focus}」。","建立判準：把問題範圍、來源可靠性、樣本限制、倫理與結論強度分層。",f"核對正解：選項 {target}「{correct}」符合題幹，因為{reason}","逐項排除：檢查其餘選項是否把單一觀察擴大、忽略來源與樣本，或未取得同意便使用私人資料。","結論回查：重新核對時間、地點、對象與證據強度；新增資料後要重新檢查，不能只沿用答案字母。"]
 d["examPatternRefs"]=refs();d["updatedAt"]="2026-09-13";d["reviewStatus"]="draft";d["provenance"]["authoringNote"]="依官方課綱、歷 J-Ⅳ-1 知識圖譜及三所公立學校公開社會科試題的地方探究、資料判讀與多方證據能力方向獨立改寫；未複製原題文字、選項、圖片或答案，待逐題學科與 Terra 複核。";p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
